```ts
type Extreme = 'earliest' | 'latest';
function findActionByCreated(
    actions: OnyxTypes.ReportAction[],
    actionNames: ReadonlyArray<OnyxTypes.ReportAction['actionName']>,
    extreme: Extreme,
    seed?: OnyxTypes.ReportAction,
): OnyxTypes.ReportAction | undefined {
    let result = seed;
    for (const action of actions) {
        if (!actionNames.includes(action.actionName)) {
            continue;
        }
        const isBetter =
            !result ||
            (extreme === 'earliest'
                ? new Date(action.created).getTime() < new Date(result.created).getTime()
                : new Date(action.created).getTime() > new Date(result.created).getTime());
        if (isBetter) {
            result = action;
        }
    }
    return result;
}
```

