```ts
function pushDiffPhrases(
    translate: LocalizedTranslate,
    phrases: SpendRulePhrase[],
    diff: SpendRuleStringDiff,
    adjective: SpendRulePhraseAdjective,
    adjectiveWord: string,
    displayNameFn: (value: string) => string,
    bodyKey: string,
    bodyChangeKey: string,
): void {
    if (diff.added.length === 1 && diff.removed.length === 1) {
        const oldValue = displayNameFn(diff.removed.at(0) ?? '');
        const newValue = displayNameFn(diff.added.at(0) ?? '');
        phrases.push({
            verb: 'changed',
            adjective,
            bodyWithAdjective: translate(`workspaceActions.expensifyCardRule.update.${bodyChangeKey}`, {adjective: adjectiveWord, oldValue, newValue}),
            bodyWithoutAdjective: translate(`workspaceActions.expensifyCardRule.update.${bodyChangeKey}`, {adjective: '', oldValue, newValue}),
        });
    } else {
        for (const value of diff.added) {
            const display = displayNameFn(value);
            phrases.push({
                verb: 'added',
                adjective,
                bodyWithAdjective: translate(`workspaceActions.expensifyCardRule.update.${bodyKey}`, {adjective: adjectiveWord, value: display}),
                bodyWithoutAdjective: translate(`workspaceActions.expensifyCardRule.update.${bodyKey}`, {adjective: '', value: display}),
            });
        }
        for (const value of diff.removed) {
            const display = displayNameFn(value);
            phrases.push({
                verb: 'removed',
                adjective,
                bodyWithAdjective: translate(`workspaceActions.expensifyCardRule.update.${bodyKey}`, {adjective: adjectiveWord, value: display}),
                bodyWithoutAdjective: translate(`workspaceActions.expensifyCardRule.update.${bodyKey}`, {adjective: '', value: display}),
            });
        }
    }
}
