function validateZipCode(zipValue: string, country: string, translate: LocaleContextProps['translate']): string | undefined {
    const countryRegexDetails = country ? (COMMON_CONST.COUNTRY_ZIP_REGEX_DATA?.[country] as {regex?: RegExp; samples?: string}) : undefined;
    const countrySpecificZipRegex = countryRegexDetails?.regex;
    if (countrySpecificZipRegex) {
