Extract the Onyx connection + fallback pattern into a reusable function, for example:

```ts
function watchReportAccessAndFallback(
    reportID: string,
    onNotFound: () => void,
) {
    let hasAttemptedFallback = false;
    const reportConnection = Onyx.connectWithoutView({
        key: `${ONYXKEYS.COLLECTION.REPORT}${reportID}`,
        callback: (updatedReport) => {
            if (!updatedReport?.errorFields?.notFound) {
                return;
            }
            if (hasAttemptedFallback) {
                return;
            }
            hasAttemptedFallback = true;
            Onyx.disconnect(reportConnection);
            onNotFound();
        },
    });

    setTimeout(() => {
        Onyx.disconnect(reportConnection);
    }, CONST.REPORT.STALE_ACCESS_TIMEOUT_MS);
}
```

