        if (!prevIsFocused && isFocused && scrollOffsetBeforeBlurRef.current < AUTOSCROLL_TO_TOP_THRESHOLD) {
            requestAnimationFrame(() => {
                scrollToBottom();
            });
        }
    }, [isFocused, prevIsFocused, scrollOffsetRef, scrollToBottom]);
}
```

