```tsx
function useSyncWithProp<T>(propValue: T): [T, React.Dispatch<React.SetStateAction<T>>] {
    const [localState, setLocalState] = useState(propValue);
    const prevProp = useRef(propValue);
    if (prevProp.current !== propValue) {
        prevProp.current = propValue;
        setLocalState(propValue);
    }
    return [localState, setLocalState];
}
```

Then usage becomes:

