Extract this into a shared helper function, for example:

```ts
function calculateDistanceSplitFields(
    amount: number,
    transaction: OnyxTypes.Transaction,
    policy: OnyxEntry<OnyxTypes.Policy>,
): {quantity: number; customUnit: TransactionCustomUnit; merchant: string} | undefined {
    const mileageRate = DistanceRequestUtils.getRate({transaction, policy: policy ?? undefined});
    const {unit, rate} = mileageRate;
    if (!rate || rate <= 0 || !transaction.comment?.customUnit) return undefined;

    const distanceInUnits = Math.abs(amount) / rate;
    const quantity = Number(distanceInUnits.toFixed(CONST.DISTANCE_DECIMAL_PLACES));
    const currency = mileageRate?.currency ?? transaction.currency ?? CONST.CURRENCY.USD;
    const merchant = getDistanceMerchantForSplitExpense(distanceInUnits, unit, rate, currency, transaction.currency);

    return {quantity, customUnit: {...transaction.comment.customUnit, quantity}, merchant};
}
```

