export const createMemoryInfo = (
    usedMemoryBytes: number | null,
    totalMemoryBytes: number | null,
    maxMemoryBytes: number | null,
    platform: string
): MemoryInfo => {
    const BYTES_PER_MB = 1024 * 1024;
    return {
        usedMemoryBytes,
        usedMemoryMB: usedMemoryBytes \!== null ? Math.round(usedMemoryBytes / BYTES_PER_MB) : null,
        totalMemoryBytes,
        maxMemoryBytes,
        usagePercentage: usedMemoryBytes \!== null && totalMemoryBytes \!== null && totalMemoryBytes > 0 
            ? parseFloat(((usedMemoryBytes / totalMemoryBytes) * 100).toFixed(2)) : null,
        freeMemoryBytes: totalMemoryBytes \!== null && usedMemoryBytes \!== null 
            ? totalMemoryBytes - usedMemoryBytes : null,
        freeMemoryMB: totalMemoryBytes \!== null && usedMemoryBytes \!== null 
            ? Math.round((totalMemoryBytes - usedMemoryBytes) / BYTES_PER_MB) : null,
        freeMemoryPercentage: totalMemoryBytes \!== null && usedMemoryBytes \!== null 
            ? parseFloat((((totalMemoryBytes - usedMemoryBytes) / totalMemoryBytes) * 100).toFixed(2)) : null,
        platform,
    };
};

export const createEmptyMemoryInfo = (platform: string): MemoryInfo => 
    createMemoryInfo(null, null, null, platform);
