/**
 * Updates the report name if it uses a formula title.
 * Returns the updated report with the recalculated name, or the original report if no update is needed.
 */
function maybeUpdateReportNameForFormulaTitle(
    report: OnyxTypes.Report,
    policy: OnyxEntry<OnyxTypes.Policy>,
): OnyxTypes.Report {
    const reportNameValuePairs = allReportNameValuePairs?.[`${ONYXKEYS.COLLECTION.REPORT_NAME_VALUE_PAIRS}${report.reportID}`];
    const titleField = reportNameValuePairs?.expensify_text_title;
    const isFormulaTitle = titleField?.type === 'formula';

    if (!isFormulaTitle) {
        return report;
    }

    const updatedReportName = recalculateOptimisticReportName(report, policy);
    if (!updatedReportName) {
        return report;
    }

    return {
        ...report,
        reportName: updatedReportName,
    };
}

