This exact logic for calculating `activeItemIndex` and `isExploreSection` is duplicated in `src/pages/Search/SearchTypeMenu.tsx` (lines 224-248). The duplicated code performs the same operations: finding matched index by similarSearchHash, falling back to matching by type, and determining if the item is in the explore section.

**Suggested fix**: Extract this logic into a shared utility function that both files can import:

```typescript
// In a shared utils file (e.g., src/libs/SearchUIUtils.ts)
export function getActiveSearchItemIndex(
    flattenedMenuItems: MenuItem[],
    similarSearchHash: number | undefined,
    isSavedSearchActive: boolean,
    queryType: string | undefined,
): [number, boolean] {
    if (isSavedSearchActive) {
        return [-1, false];
    }

    let isMatchedIndex = flattenedMenuItems.findIndex((item) => item.similarSearchHash === similarSearchHash);
    if (isMatchedIndex === -1) {
        isMatchedIndex = flattenedMenuItems.findIndex((item) => {
            if (queryType === CONST.SEARCH.DATA_TYPES.EXPENSE) {
                return item.key === CONST.SEARCH.SEARCH_KEYS.EXPENSES;
            }
            if (queryType === CONST.SEARCH.DATA_TYPES.EXPENSE_REPORT) {
                return item.key === CONST.SEARCH.SEARCH_KEYS.REPORTS;
            }
            if (queryType === CONST.SEARCH.DATA_TYPES.CHAT) {
                return item.key === CONST.SEARCH.SEARCH_KEYS.CHATS;
            }
            return false;
        });
    }
    const matchedItemKey = isMatchedIndex \!== -1 ? flattenedMenuItems.at(isMatchedIndex)?.key : undefined;
    const isExploreSection = \!\!matchedItemKey && 
        ([CONST.SEARCH.SEARCH_KEYS.EXPENSES, CONST.SEARCH.SEARCH_KEYS.REPORTS, CONST.SEARCH.SEARCH_KEYS.CHATS] as string[]).includes(matchedItemKey);
    return [isMatchedIndex, isExploreSection];
}
```

Then use it in both files:
