Code duplication: The filtering logic for Guide/AM is duplicated across 4 files (BaseOnboardingWorkspaceInvite.tsx, WorkspaceInvitePage.tsx, and both AssigneeStep.tsx files). This violates the DRY principle and increases maintenance overhead.

Suggested fix: Extract the filtering logic into a reusable utility function:

```tsx
// In a shared utils file (e.g., src/libs/PolicyUtils.ts)
function filterGuideAndAccountManager<T extends {login?: string | null; alternateText?: string | null}>(
    items: T[],
    assignedGuideEmail?: string,
    accountManagerLogin?: string,
): T[] {
    return items.filter((item) => {
        const itemLogin = item.login?.toLowerCase();
        const itemAltText = item.alternateText?.toLowerCase();

        if (assignedGuideEmail && (itemLogin === assignedGuideEmail || itemAltText === assignedGuideEmail)) {
            return false;
        }
        if (accountManagerLogin && (itemLogin === accountManagerLogin || itemAltText === accountManagerLogin)) {
            return false;
        }
        return true;
    });
}

// Usage:
const assignedGuideEmail = policy?.assignedGuide?.email?.toLowerCase();
const accountManagerLogin = account?.accountManagerAccountID 
    ? personalDetails?.[Number(account.accountManagerAccountID)]?.login?.toLowerCase() 
    : undefined;

const filteredPersonalDetails = filterGuideAndAccountManager(
    availableOptions.personalDetails,
    assignedGuideEmail,
    accountManagerLogin
);
```

