    const capturedReportID = reportID;
    const capturedReportAction = reportAction ?? null;
    reportIDRef.current = reportID;
    reportActionRef.current = capturedReportAction;

    showConfirmModal({
        // ... modal config
    }).then((result) => {
        // Use capturedReportAction instead of reportActionRef.current
        const currentReportAction = capturedReportAction;
        // ...
    });
};
```

